 "content": "def transform(grid):
    """Remove isolated noise-colored cells; preserve the two solid blocks."""
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # The substantial non-background objects are represented by their colors;
    # erase any cells of other colors, and fill color-4 holes within the blocks.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (background, 5, 8):
                out[r][c] = background
    # Remove any noise through dominant background determination and restore
    # full rectangular extent of the large 5 and 8 regions.
    for color in (5, 8):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if cells:
            r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
            c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color
    return out
